[CmdletBinding()]
param()

$ErrorActionPreference = "Stop"
Set-StrictMode -Version Latest

$target = "C:\Users\mozar\TriggerCMD-Scripts\Control\system-inventory.ps1"
$payload = @'

'@
$bytes = [Convert]::FromBase64String(($payload -replace "`r?`n", ""))
$input = New-Object IO.MemoryStream(,$bytes)
$gzip = New-Object IO.Compression.GzipStream($input,[IO.Compression.CompressionMode]::Decompress)
$output = New-Object IO.MemoryStream
$gzip.CopyTo($output)
$gzip.Dispose()
$input.Dispose()
[IO.File]::WriteAllBytes($target,$output.ToArray())
$output.Dispose()
$hash = (Get-FileHash -LiteralPath $target -Algorithm SHA256).Hash.ToLowerInvariant()
if ($hash -ne "7d3e73107febf9c200b4115099fac6d71591a7ab386a66cfeecbd88f3dba2505") {
    throw "Decoded system inventory collector hash mismatch: $hash"
}
Write-Output "Installed=$target; SHA256=$hash"
